<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF">REM</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379"> Set</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379"> NODE_TLS_REJECT_UNAUTHORIZED=</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66">0</span></span>
